// distFS embeds the SPA build tree (internal/web/dist/). The `all:` prefix
// includes files Go would otherwise skip (e.g. .html / dotfiles). Whether the
// content is the Phase-1 placeholder or the Phase-2 React build is transparent
// to this package — it serves whatever bytes are embedded.
//
//go:embed all:dist
var distFS embed.FS

// indexHTML is the embedded SPA shell, read once at init. A missing
// dist/index.html is a build-input failure (Task 01 owns the placeholder) and
// panics loudly rather than serving garbage at runtime.
var indexHTML = mustReadIndex()

// Options configures the web Handler. The zero value is the production
// configuration (immutable asset cache + no-cache index).
type Options struct {
	// DevMode true ⇒ sends Cache-Control: no-cache everywhere (disables the
	// immutable /assets/* header). For running the Go server alongside the
	// Vite dev proxy, where dist/ is served by Vite and the Go server only
	// proxies the API. Default false (production embedded dist).
	DevMode bool
}

// Handler composes the api router with the embedded SPA. apiHandler is mounted
// at /api/* (it carries its own auth middleware); everything else is served
// from the embedded dist with client-route fallback. A nil apiHandler is valid
// — the /api/* mount is skipped, so tests can exercise the SPA/swagger surface
// alone. /openapi.{yaml,json} + /docs are registered by swagger.go (Task 12);
// until then they fall through to the SPA fallback (a known gap Task 12
// closes).
func Handler(apiHandler http.Handler, opts Options) http.Handler {
	r := chi.NewRouter()
	if apiHandler != nil {
		// All methods: the api router dispatches by its own method table.
		r.Handle("/api/*", apiHandler)
	}
	registerSwagger(r) // /openapi.{yaml,json} + /docs — ahead of the SPA fallback.
	r.Get("/", func(w http.ResponseWriter, r *http.Request) { serveIndex(w, opts) })
	r.Get("/assets/*", func(w http.ResponseWriter, r *http.Request) { serveAsset(w, r, opts) })
	r.NotFound(func(w http.ResponseWriter, r *http.Request) {
		// Broken hashed asset URLs fail fast (no fallback) so a stale hash is
		// visible, not papered over by index.html. Every other unmatched path
		// is a client-side route → SPA fallback.
		if strings.HasPrefix(r.URL.Path, "/assets/") {
			http.NotFound(w, r)
			return
		}
		serveIndex(w, opts)
	})
	return r
}

// serveIndex writes the embedded index.html with the no-cache header (the SPA
// shell must revalidate so a new deploy is picked up on the next navigation).
func serveIndex(w http.ResponseWriter, opts Options) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", cacheControl(false, opts))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(indexHTML)
}

// serveAsset writes a hashed asset under /assets/* with the immutable cache
// header. A missing asset returns 404 (fail fast — see Handler NotFound). The
// path is read from the embed.FS which is traversal-safe by construction.
func serveAsset(w http.ResponseWriter, r *http.Request, opts Options) {
	name := strings.TrimPrefix(r.URL.Path, "/assets/")
	if name == "" {
		http.NotFound(w, r)
		return
	}
	b, err := distFS.ReadFile("dist/assets/" + name)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", contentTypeFor(name))
	w.Header().Set("Cache-Control", cacheControl(true, opts))
	_, _ = w.Write(b)
}

// cacheControl returns the asset cache header when isAsset, else the index
// header. DevMode collapses both to no-cache (Vite dev proxy).
func cacheControl(isAsset bool, opts Options) string {
	if opts.DevMode || !isAsset {
		return "no-cache"
	}
	return "public, max-age=31536000, immutable"
}

// contentTypeFor maps a Vite-emitted asset extension to its Content-Type.
// Inlined (rather than importing mime) so the package stays inside its allowed
// import set; Vite hashes filenames but preserves extensions, so extension
// lookup is sufficient and deterministic.
func contentTypeFor(name string) string {
	switch path.Ext(name) {
	case ".js", ".mjs":
		return "application/javascript; charset=utf-8"
	case ".css":
		return "text/css; charset=utf-8"
	case ".html":
		return "text/html; charset=utf-8"
	case ".json":
		return "application/json; charset=utf-8"
	case ".svg":
		return "image/svg+xml"
	case ".png":
		return "image/png"
	case ".jpg", ".jpeg":
		return "image/jpeg"
	case ".ico":
		return "image/x-icon"
	case ".woff":
		return "font/woff"
	case ".woff2":
		return "font/woff2"
	default:
		return "application/octet-stream"
	}
}

// mustReadIndex loads dist/index.html at init. A failure here means the embed
// inputs are wrong (Task 01 owns the placeholder) — fail fast at startup, not
// per-request.
func mustReadIndex() []byte {
	b, err := distFS.ReadFile("dist/index.html")
	if err != nil {
		panic("web: embedded dist/index.html missing: " + err.Error())
	}
	return b
}
